        "svc_5_good_desc": "[EN] Inspeccin de cmara bsica hasta 50 pies. Identificacin de bloqueos y entrega de video en memoria USB.",
        "svc_5_better_desc": "[EN] Inspeccin profunda SeeSnake con localizacin por sonar. Trazamos y marcamos la ubicacin exacta y profundidad del problema en la superficie.",
        "svc_5_best_desc": "[EN] Inspeccin HD y modelado. Mapeo completo del sistema, trazado de sonar y reporte de Plomería Técnica digital detallando pendientes, intrusiones y opciones de recubrimiento sin zanja (CIPP).",
        "svc_6_good_desc": "[EN] Excavacin tradicional e instalación de PVC SDR-35. Cumple con los cdigos locales y provee una solucin probada de flujo por gravedad.",
        "svc_6_better_desc": "[EN] Reemplazo con ABS Cdula 40. Tubera de ncleo slido superior, instalada con cama de grava estabilizadora y registros de limpieza bidireccionales.",
        "svc_6_best_desc": "[EN] Reemplazo sin zanja (Trenchless) con polietileno de alta densidad (HDPE) de juntas fusionadas. Tubera continua sin costuras, imposible de penetrar por races. Garanta de por vida.",
        "svc_7_good_desc": "[EN] Instalacin de un calentador atmosfrico estndar de 50 galones. Reemplazo directo sin modificaciones elctricas complejas.",
        "svc_7_better_desc": "[EN] Instalacin de calentador Hbrido Rheem ProTerra. Incluye vlvula de mezcla trmica, panel de control digital y eficiencia que califica para incentivos fiscales.",
        "svc_7_best_desc": "[EN] Bradford White AeroTherm con integracin Wi-Fi completa. Modos de programacin inteligente, bomba ultra-silenciosa y sensores de deteccin de fugas integrados desde la fbrica.",
        "svc_8_good_desc": "[EN] Instalacin de vlvula PRV de latn estndar de grado residencial. Estabiliza la presión principal previniendo daños a corto plazo.",
        "svc_8_better_desc": "[EN] Wilkins 600XL con manmetro de lectura integrada. Permite un monitoreo visual y ajustes precisos sin requerir herramientas adicionales de Diagnóstico.",
        "svc_8_best_desc": "[EN] Vlvula Watts LFN45B. Incluye filtro en lnea integrado para proteger la vlvula de sedimentos, acompaado de un tanque de expansin trmica para manejar cambios volumtricos.",
        "svc_9_good_desc": "[EN] Respuesta primaria. Cierre del agua principal y uso de tapones SharkBite temporales para detener la emergencia y permitir secado.",
        "svc_9_better_desc": "[EN] Aislamiento del sector. Instalacin de válvulas de aislamiento permanente de Cobre ProPress, permitiendo dar agua al resto de la casa mientras el sector daado queda aislado.",
        "svc_9_best_desc": "[EN] Resolucin y reestructuracin. Construccin de un manifold de aislamiento completo y soldadura/prensado definitivo de la falla. Solucin permanente de una sola visita.",
        "svc_10_good_desc": "[EN] Trazado de lneas principales con pintura/banderas en superficie y un esquema dibujado profesionalmente indicando profundidades y direcciones.",
        "svc_10_better_desc": "[EN] Superposicin digital en AutoCAD 2D. Entregamos un archivo digital planimtrico que se integra perfectamente con los planos arquitectnicos de la propiedad.",
        "svc_10_best_desc": "[EN] Modelado BIM/Revit en 3D. Cada nodo, tubera y vlvula geolocalizado en un modelo digital con metadatos, esencial para property managers y edificios comerciales.",
        "svc_11_good_desc": "[EN] Navien NPE-A2 serie sin condensacin. Excelente para reemplazos rpidos y proveer flujo continuo con una eficiencia superior a los tanques estndar.",
        "svc_11_better_desc": "[EN] Rinnai RU Sensei de Condensacin. Altsima eficiencia (0.95 UEF), quemadores de modulacin inteligente y controles de pared digitales.",
        "svc_11_best_desc": "[EN] Navien NPE-240A2 Condensing con bomba de recirculacin ComfortFlow interna y tanque buffer integrado. Agua caliente instantnea en cada grifo, cero tiempos de espera.",
        "svc_12_good_desc": "[EN] Instalacin de ensamblaje RPZ (Reduced Pressure Zone) Wilkins 375 estndar. Cumplimiento inmediato con las regulaciones de la ciudad.",
        "svc_12_better_desc": "[EN] Ensamblaje Watts Serie 009 de alto flujo. Vlvulas de control de cuarto de vuelta y cuerpo de bronce sin plomo para aplicaciones comerciales severas.",
        "svc_12_best_desc": "[EN] Febco 860 RPZ equipado con sensor IoT de cada de presión. Monitorea los diferenciales de presión en tiempo real y alerta al administrador sobre bloqueos o fallas antes de la inspeccin anual.",
        "svc_13_good_desc": "[EN] Instalacin de accesorios estndar nivel residencial (Delta/Moen). Incluye nuevas lneas de suministro trenzadas de acero inoxidable y sellos nuevos.",
        "svc_13_better_desc": "[EN] Instalacin de herrajes de gama media-alta (Moen Align, Grohe) con acabados resistentes a manchas. Sellado con silicona comercial anti-moho.",
        "svc_13_best_desc": "[EN] Instalacin e integracin de grifera inteligente (Kohler Artifacts Smart Touch / Voice Control). Calibracin de temperatura preestablecida y cableado del módulo sensor.",
        "svc_14_good_desc": "[EN] Test rápidas in-situ. Medicin de TDS (Slidos Disueltos Totales), prueba de dureza por gotas qumicas y nivel de cloro libre.",
        "svc_14_better_desc": "[EN] Envo de muestra a laboratorio certificado para un panel de 16 puntos (metales pesados, plomo, nitratos, VOCs). Reporte completo en 5 das hbiles.",
        "svc_14_best_desc": "[EN] Test in-situ más instalación permanente de un medidor TDS digital en lnea en el fregadero de su cocina. Monitoreo en tiempo real de la pureza de su agua.",
        "svc_15_good_desc": "[EN] Desazolve pesado utilizando barrena elctrica seccional (cable auger) de 7/8. Ideal para taponamientos duros de papel o races finas.",
        "svc_15_better_desc": "[EN] Limpieza con sistema de Hydro-Jetting a 4000 PSI en toda la longitud de la lnea afectada. Restaura la tubera eliminando escamas de sarro y grasa emulsificada.",
        "svc_15_best_desc": "[EN] Hydro-Jetting pesado con boquillas desincrustantes, seguido de una inspeccin final con cmara HD y aplicacin de tratamiento qumico inhibidor de races RootX para prevencin a 12 meses.",

