        "lp_t2_n": "- Carlos V., San Diego",
        "lp_t3_d": "\"Mi lavabo olía fatal. Gracias al truco del aereador y el vinagre, no tuve que gastar en limpiadores químicos costosos. ¡Funcionó perfecto!\"",
        "lp_t3_n": "- Elena R., San Francisco",
