        "comic_step_4": "Prueba de flujo y restauracin.",
        "svc_1_good_desc": "Resolucin mediante un Diagnóstico visual y acstico bsico. Se emplea un parche estándar y equipo manual para fugas accesibles. Ideal para reparaciones rpidas de bajo impacto.",
        "svc_1_better_desc": "Integracin de termografa (FLIR) y prueba de cada de presión. Reparacin mediante recubrimiento epxico, lo cual garantiza una mayor longevidad sin reemplazar la lnea completa.",
        "svc_1_best_desc": "Mapeo estructural completo y aislamiento sectorizado. Reparacin definitiva utilizando un segmento de repipe en Cobre Tipo L con tecnología de prensado ProPress. Esta es la solucin de grado comercial que garantiza integridad a largo plazo.",
        "svc_2_good_desc": "Reemplazo utilizando tubera PEX-B con conectores tipo Crimp. Incluye prueba de presión a 100 PSI. Es una solucin confiable y econmica para restablecer la funcionalidad del sistema.",
        "svc_2_better_desc": "Reemplazo con tubera PEX-A Uponor (Expansin), que ofrece mayor flujo y resistencia a congelamientos. Menos conectores mecnicos significa menor riesgo de fugas a futuro.",
        "svc_2_best_desc": "Reemplazo en Cobre Tipo L con tecnología de prensado ProPress (sin soldadura, sin fuego). Flujo mximo, propiedades antimicrobianas naturales y durabilidad absoluta de grado comercial.",
