        "law_title": "Regulaciones BAAQMD & Cdigo de Instalacin",
        "law_subtitle": "La guía definitiva sobre el mandato 2027 de cero emisiones (Zero-NOx) para el ÁÁrea de la Bahía, los nuevos tipos de calentadores y los estrictos requisitos de instalación de CSLB y el Título 24 de California.",
        "law_sec1_title": "1. El Mandato de BAAQMD 2027 (Regulacin 9, Regla 6)",
        "law_sec1_p1": "El Distrito de Gestin de la Calidad del Aire del ÁÁrea de la Bahía (BAAQMD) ha emitido una enmienda histrica para reducir la contaminacin por xidos de nitrgeno (NOx).",
        "law_sec1_p2": "<strong>¿Quésignifica esto?</strong> A partir del 1 de enero de 2027, serilegal vender o instalar nuevos calentadores de agua residenciales de gas natural que emitan NOx. Esto significa la eliminacin gradual completa de los calentadores tradicionales a gas en el ÁÁrea de la Bahía.",
        "law_sec1_li1": "<strong>Impacto Inmediato:</strong> Los reemplazos de emergencia después de 2027 requerirán exclusivamente equipos eléctricos de cero emisiones.",
        "law_sec1_li2": "<strong>Transicin:</strong> Se insta a los propietarios a migrar a calentadores de bomba de calor (Heat Pump) antes del colapso de inventario de 2027.",
        "law_sec2_title": "2. Tipos de Calentadores de Agua (Transicin a Elctrico)",
        "law_sec2_p1": "Comprender las tecnologías aprobadas para la transicin energética de California es vital para cumplir con el Título 24 (Title 24).",
        "law_sec2_li1": "<strong>Bomba de Calor Hbrida (Heat Pump):</strong> Extrae calor del aire ambiental para calentar el agua, logrando eficiencias superiores al 300%. Es la opcin #1 requerida por el estado y califica para los mximos reembolsos (Rebates).",
        "law_sec2_li2": "<strong>Elctricos de Tanque Estndar:</strong> Utilizan resistencias trmicas, menos eficientes y generalmente penalizados bajo clculos estrictos del Título 24, pero permitidos.",
        "law_sec2_li3": "<strong>Elctricos Tankless (Sin Tanque):</strong> Calientan el agua al instante. Aunque no emiten NOx, requieren un amperaje masivo (a menudo paneles eléctricos de más de 200A) y rara vez son viables sin actualizaciones elctricas costosas.",
        "law_sec3_title": "3. Especificaciones del Cdigo (CSLB y Title 24)",
        "law_sec3_p1": "Instalar un calentador no es solo conectar agua. Morales Plumbing garantiza el cumplimiento estricto del Código Uniforme de Plomería (UPC) de California:",
        "law_sec3_li1": "<strong>Sujecin Ssmica (Earthquake Straps):</strong> Ley de California requiere correas dobles en el tercio superior e inferior, ancladas directamente a montantes de pared para evitar el vuelco durante terremotos.",
        "law_sec3_li2": "<strong>Tanque de Expansin Trmica:</strong> Obligatorio en sistemas de plomería cerrados para absorber el exceso de presión, protegiendo las tuberas del hogar y evitando explosiones de válvulas.",
        "law_sec3_li3": "<strong>Bandeja de Drenaje (Drain Pan):</strong> Requerida si el calentador esten una plataforma interior, en tico o espacio donde una fuga cause daos a la estructura. La bandeja debe tener tubera que drene al exterior.",
        "law_sec3_li4": "<strong>Vlvula T&P (Temperature & Pressure Relief):</strong> Crtica para la seguridad, su lnea de descarga debe llevar el agua caliente a un desage seguro, tpicamente al exterior.",
        "law_btn_back": "Ver Paquetes de Instalacin Certificados",
        "btn_eco_systems": "? Sistemas Eco de Calentadores",
