        "network_link": "> RED: ORION TECH",
        "service_copper_title": "Renovaciones en Cobre Elite",
        "service_copper_desc": "Infraestructura hidrulica de alta gama con cumplimiento UPC 2024.",
        "service_copper_detail": "CONTENIDO: Sistemas completos de tuberas de cobre (Tipos L, M, K) para infraestructura residencial y comercial. PROPSITO: Integridad estructural garantizada y eficiencia de flujo. USO: Renovaciones, ampliaciones, construcciones nuevas y reparaciones. POTENCIALIDADES: Vida til de más de 50 aos, sin microplsticos. COSTOS: Reduccin del 30% en mantenimiento a largo plazo vs PEX. COMPETENCIA: Superamos los estándares locales con soldadura especializada. PLUS: Plomería Tcúnica Sostenible, protocolos internacionales y procesos Lean. COPYRIGHT: © 2026 Morales Plumbing. Todos los derechos reservados.",
        "service_expansion_title": "Ampliaciones Hidrulicas Pro",
        "service_expansion_desc": "Expansin estratgica de redes para renovaciones y anexos (ADUs).",
        "service_expansion_detail": "CONTENIDO: Bloques de expansin hidrulica modular. PROPSITO: Integracin perfecta de nuevos accesorios sin prdida de presión. USO: Adiciones comerciales y ampliaciones residenciales. POTENCIALIDADES: Escalabilidad infinita. COSTOS: Evita el rediseo total del sistema. PLUS: Plomería Tcúnica avanzada y procesos Lean. COPYRIGHT: © 2026 Morales Plumbing. Todos los derechos reservados.",
        "service_construction_title": "Plomería Tcúnica de Obra Nueva",
        "service_construction_desc": "Diseo y despliegue integral de infraestructura para edificios inteligentes.",
        "service_construction_detail": "CONTENIDO: Planos CAD, Rough-in y acabados de lujo. PROPSITO: Excelencia tcúnica desde cero. USO: Nuevos edificios residenciales y comerciales. POTENCIALIDADES: Valorizacin inmediata de la propiedad. COSTOS: Optimizacin de materiales mediante Lean Process. PLUS: Protocolos Ambientales Internacionales. COPYRIGHT: © 2026 Morales Plumbing. Todos los derechos reservados.",
        "service_repair_title": "Diagnstico y Reparacin Smart",
        "service_repair_desc": "Restauracin tcúnica mediante termografa y acstica no invasiva.",
        "service_repair_detail": "CONTENIDO: Diagnstico por termografa y reparacin de precisin. PROPSITO: Restauracin inmediata de la operatividad. USO: Emergencias y mantenimiento preventivo. POTENCIALIDADES: Deteccin temprana de fallas invisibles. COSTOS: Evita daos estructurales costosos. PLUS: Joe AI Assistant para diagnsticos. COPYRIGHT: © 2026 Morales Plumbing. Todos los derechos reservados.",
        "service_septic_title": "Sistemas Spticos Avanzada",
        "service_septic_desc": "Sistemas de tratamiento in-situ para infraestructura rural y eco-sostenible.",
        "service_water_title": "Sistemas de Recoleccin Hdrica",
        "service_water_desc": "Plomería Tcúnica de captura de lluvia y reutilizacin de aguas grises estratgicas.",
        "faq_title": "P&R | Centro Tcnico",
        "faq_cat_plumbing": "Sistemas de Plomería",
        "faq_cat_eco": "Mezcla de Eco-Plomería",
        "faq_cat_env": "Regulaciones Ambientales",
        "faq_q1": "¿Por qué usar cobre en lugar de PEX para construcciones nuevas?",
        "faq_a1": "El cobre proporciona una durabilidad superior, resistencia al fuego y previene el crecimiento bacteriano. Bajo el UPC de California, sigue siendo el estándar de oro para el valor de alta gama. Por otro lado, el PEX ofrece una flexibilidad excepcional, menos conexiones de unin (reduciendo puntos de fuga), instalación más rpida y menores costos iniciales de material. <span class=\"comic-choice\">La decisin es suya</span>: elija la longevidad premium y el valor clsico del cobre, o la rentabilidad moderna y la resiliencia elstica del PEX.",
        "faq_q2": "Cules son las regulaciones spticas y ambientales de California para 2026?",
        "faq_a2": "Las regulaciones se centran en la reduccin de nitrgeno, proteccin de aguas subterrneas y eficiencia en la reutilizacin de agua. Morales Plumbing garantiza el 100% de cumplimiento mediante Plomería Tcúnica avanzada y protocolos de la Junta de Agua. Adems, diseamos sistemas spticos estándar que minimizan los costos iniciales utilizando rutas de permisos locales tradicionales. <span class=\"comic-choice\">La decisin es suya</span>: invierta en sistemas ecolgicos avanzados para anticiparse a las normas de 2030, o seleccione una configuracin estándar de bajo costo inmediato.",
        "faq_q3": "Cmo beneficia el Proceso Lean y la Plomería Tcúnica Sostenible a mi proyecto?",
        "faq_a3": "Al eliminar desperdicios y usar materiales sostenibles, reducimos costos en un 25% y plazos en un 30%. Nuestros protocolos aseguran una menor huella de carbono y mayor ROI de infraestructura. Como alternativa, ofrecemos mtodos de construccin clsicos enfocados en la mxima personalizacin y redundancia estructural manual absoluta sin los lmites del proceso Lean. <span class=\"comic-choice\">La decisin es suya</span>: elija el proceso ecolgico Lean acelerado para mxima eficiencia, o nuestra construccin manual clsica para una personalizacin tradicional a medida.",
        "faq_q4": "Puedo integrar la recoleccin de agua en mi sistema de plomería existente?",
        "faq_a4": "S, nos especializamos en la adaptacin de captaciones y sistemas de aguas grises a redes existentes, reduciendo significativamente la dependencia municipal y los costos operativos.",
        "faq_q5": "Cul es la ventaja del marco Morales Plumbing PLUS?",
        "faq_a5": "Combina la experiencia CSLB C-36 con Plomería Tcúnica Sostenible, diagnsticos por IA y Proceso Lean, brindando un nivel de precisin y sostenibilidad inigualable.",
        "faq_q6": "Cmo asegura Morales Plumbing el cumplimiento del UPC?",
        "faq_a6": "Nuestros ingenieros cuentan con certificacin CSLB C-36 y utilizan protocolos de verificacin por IA para asegurar que cada conexin supere los estándares de California. Adems, ofrecemos inspecciones fsicas tradicionales de doble inspector y listas de verificacin manuales para clientes que prefieren la supervisin mecúnica clsica. <span class=\"comic-choice\">La decisin es suya</span>: elija nuestra validacin digital de alta precisión asistida por IA, o nuestra inspeccin humana manual probada en el tiempo con garantas mecúnicas.",
        "faq_q7": "¿Quémtricas 'Lean' especficas rastrean?",
        "faq_a7": "Rastreamos Takt Time, Lead Time y First-Pass Yield para asegurar un flujo de trabajo predecible y sin desperdicios en proyectos de gran escala. Al mismo tiempo, apoyamos el seguimiento clsico por hitos del proyecto y auditoras de horas de trabajo tradicionales para una supervisin más simple y directa. <span class=\"comic-choice\">La decisin es suya</span>: optimice con tableros de datos Lean en tiempo real, o gestione mediante hitos tradicionales sencillos.",
        "faq_q8": "Cmo puedo preparar mi infraestructura para el futuro?",
        "faq_a8": "Al integrar sistemas de recoleccin de agua y reutilizacin de aguas grises hoy, evita futuros mandatos y aumenta el valor de su propiedad hasta en un 15%. Como alternativa, puede optar por un diseo pasivo ultra confiable con tuberas de alta durabilidad y colectores simplificados que minimizan las partes mecúnicas activas. <span class=\"comic-choice\">La decisin es suya</span>: invierta en tecnologías de agua activas y sostenibles, o seleccione un sistema de bucle pasivo de bajo mantenimiento y alta confiabilidad.",
        "service_septic_detail": "CONTENIDO: Sistemas avanzados de biodigestores y campos de infiltracin. PROPSITO: Tratamiento de aguas residuales ecolgico y autnomo. USO: Zonas rurales y proyectos sostenibles. POTENCIALIDADES: Independencia total del drenaje municipal. COSTOS: Eliminacin de cuotas de alcantarillado. COMPETENCIA: Plomería Tcúnica biolgica vs tanques spticos simples. PLUS: Cumplimiento ambiental estricto. LEAN: Mantenimiento automatizado.",
        "service_water_detail": "CONTENIDO: Plomería Tcúnica de recoleccin de lluvia y tratamiento de aguas grises. PROPSITO: Autonoma hdrica extrema y conservacin. USO: Riego y uso domstico reciclado. POTENCIALIDADES: Resiliencia ante sequas. COSTOS: Reduccin del 60% en consumo de agua potable. COMPETENCIA: Filtracin avanzada vs barriles simples. PLUS: Protocolos de sostenibilidad gubernamentales. LEAN: Automatizacin de ciclos hdricos.",
