        "pb_svc_1_good_time": "2-3 hrs",
        "pb_svc_1_better_just": "[Scope] Premium detection for multi-zone pressure drops. Includes isolating hot/cold manifolds, introducing inert tracer gas, and precise pinpointing under hardscapes.",
