        "lbl_starting_at": "Kho?n d?u tu u?c tnh b?t d?u t?:",
        "lbl_est_range": "*Chi phcu?i cùng thay d?i tùy thu?c vào dnh git?i ch?, yêu c?u mã và nâng c?p di?n/khd?t.",
        "promo_wp_good_comic_1": "1. X? và tho bình nng l?nh gas cu.",
        "promo_wp_good_comic_2": "2. L?p d?t bom nhi?t hybrid tiêu chu?n.",
        "promo_wp_good_comic_3": "3. Ð?m b?o tuân th? cc quy d?nh BAAQMD 2027.",
        "promo_wp_good_comic_4": "4. H? th?ng ho?t d?ng: Nu?c nng dng tin c?y và thân thi?n v?i môi tru?ng.",
        "promo_wp_better_comic_1": "1. L?p d?t thi?t b? ProTerra Cao c?p.",
        "promo_wp_better_comic_2": "2. Ð?i ngu k? thu?t k?t n?i h? th?ng v?i WiFi t?i nhà.",
        "promo_wp_better_comic_3": "3. Kch ho?t c?m bi?n pht hi?n rò r? tch h?p.",
        "promo_wp_better_comic_4": "4. Khch hàng t?n hu?ng quy?n ki?m sot toàn b? và c?nh bo qua ?ng d?ng.",
        "promo_wp_best_comic_1": "1. Ðnh gib?ng di?n và cc nâng c?p c?n thi?t.",
        "promo_wp_best_comic_2": "2. Ð?t AeroTherm 80 gallon d? d?t công su?t t?i da.",
        "promo_wp_best_comic_3": "3. B?o v? an?t kp và công ngh? ho?t d?ng c?c êm.",
        "promo_wp_best_comic_4": "4. Tch h?p nhà thông minh t?i da và tang gitr? tài s?n.",
        "law_title": "¿Quéy d?nh BAAQMD & Mã L?p d?t",
        "law_subtitle": "Hu?ng d?n t?i uu v? l?nh Zero-NOx 2027 cho Khu v?c V?nh, cc lo?i my nu?c nng m?i, và cc yêu c?u l?p d?t nghiêm ng?t c?a CSLB và Title 24 c?a California.",
        "law_sec1_title": "1. L?nh BAAQMD 2027 (¿Quéy d?nh 9, ¿Quéy t?c 6)",
        "law_sec1_p1": "¿Qué?n ¿Qué?n lý Ch?t lu?ng Không khKhu v?c V?nh (BAAQMD) dã ban hành m?t s?a d?i l?ch s? d? gi?m ô nhi?m nito oxit (NOx).",
        "law_sec1_p2": "<strong>Ði?u này cý nghia gì?</strong> B?t d?u t? ngày 1 thng 1 nam 2027, vi?c bn ho?c l?p d?t my nu?c nng dân d?ng ch?y b?ng khd?t t? nhiên m?i pht th?i NOx s? là b?t h?p php. Ði?u này cnghia là lo?i b? hoàn toàn cc my nu?c nng b?ng khd?t truy?n th?ng ? Khu v?c V?nh.",
        "law_sec1_li1": "<strong>Tc d?ng T?c thì:</strong> Cc thay th? kh?n c?p sau nam 2027 s? yêu c?u thi?t b? di?n không pht th?i d?c quy?n.",
        "law_sec1_li2": "<strong>Chuy?n d?i:</strong> Ch? nhà du?c khuy?n co nên chuy?n sang my nu?c nng Bom nhi?t (Heat Pump) tru?c khi c?n ki?t hàng t?n kho vào nam 2027.",
        "law_sec2_title": "2. Cc lo?i My nu?c nng (Chuy?n d?i Ði?n)",
        "law_sec2_p1": "Vi?c hi?u cc công ngh? du?c phê duy?t cho qutrình chuy?n d?i nang lu?ng c?a California là r?t quan tr?ng d? tuân th? Title 24.",
        "law_sec2_li1": "<strong>Bom nhi?t H?n h?p (Heat Pump):</strong> Trch xu?t nhi?t t? không khxung quanh d? làm nng nu?c, d?t hi?u su?t trên 300%. Ðây là tùy ch?n s? 1 theo yêu c?u c?a ti?u bang và d? di?u ki?n nh?n cc kho?n hoàn tr? t?i da.",
        "law_sec2_li2": "<strong>Bình Ði?n Tiêu chu?n:</strong> S? d?ng cc ph?n t? nhi?t, km hi?u qu? hon và thu?ng b? ph?t theo cc tnh ton nghiêm ng?t c?a Title 24, nhung du?c php.",
        "law_sec2_li3": "<strong>Ði?n Không bình ch?a (Tankless):</strong> Làm nng nu?c ngay l?p t?c. M?c dù chng không pht th?i NOx, chng c?n cu?ng d? dòng di?n c?c l?n (thu?ng là b?ng di?u khi?n 200A+) và hi?m khi kh? thi n?u không nâng c?p di?n t?n km.",
        "law_sec3_title": "3. Thông s? k? thu?t c?a Mã (CSLB & Title 24)",
        "law_sec3_p1": "L?p d?t my nu?c nng không ch? là n?i du?ng ?ng nu?c. Morales Plumbing d?m b?o tuân th? nghiêm ng?t Mã H? th?ng ?ng nu?c Th?ng nh?t (UPC) c?a California:",
        "law_sec3_li1": "<strong>Dây deo ch?ng Ð?ng d?t (Earthquake Straps):</strong> Lu?t California yêu c?u s? d?ng dây deo dôi ? m?t ph?n ba trên và du?i, du?c neo tr?c ti?p vào dinh tn tu?ng d? trnh l?t khi cd?ng d?t.",
        "law_sec3_li2": "<strong>Bình Giãn n? Nhi?t:</strong> B?t bu?c d?i v?i cc h? th?ng ?ng nu?c kn d? h?p th? p su?t du th?a, b?o v? du?ng ?ng trong nhà và ngan ng?a n? van.",
        "law_sec3_li3": "<strong>Khay thot nu?c (Drain Pan):</strong> B?t bu?c n?u my nu?c nng n?m trên n?n t?ng trong nhà, gc mi ho?c không gian mà s? rò r? cth? gây hu h?i c?u trc. Khay ph?i c?ng d?n nu?c ra ngoài tr?i.",
        "law_sec3_li4": "<strong>Van T&P (Van x? Nhi?t d? & Áp su?t):</strong> ¿Quéan tr?ng d?i v?i an toàn, du?ng x? c?a nph?i d?n nu?c nng d?n c?ng m?t cch an toàn, thu?ng là ngoài tr?i.",
        "law_btn_back": "Xem cc Gi L?p d?t du?c Ch?ng nh?n",
