        "promo_ttt_legal_rebates_title": "2. Incentives and Rebates:",
        "promo_ttt_legal_rebates_desc": "Heat pumps qualify for the Federal IRA Tax Credit (up to $2,000) and TECH Clean CA rebates (up to $3,100). Funds are limited and depend on zip code.",
        "promo_ttt_legal_apply_title": "3. Application Requirements:",
        "promo_ttt_legal_apply_desc": "Applies to residential homeowners replacing old equipment. If your electrical panel requires a 240V upgrade, you may qualify for additional subsidies.",
        "promo_ttt_legal_time_title": "4. Validity and Responsibility:",
        "promo_ttt_legal_time_desc": "The transition window is now. Morales Plumbing provides certified equipment and rebate paperwork, but does not guarantee State approval or payment timelines.",
        "footer_print_watermark": "© MORALES PLUMBING 2026",

