        "lbl_client_view": "Gc nhìn Khch hàng:",
        "lbl_tech_view": "Thông s? K? thu?t & V?t li?u (3 C?p d?):",
        "doc_title": "Ð? xu?t chi?n lu?c",
        "doc_subtitle": "Làm ch? h? th?ng ?ng nu?c thông minh & K? thu?t môi tru?ng",
        "sig_name": "Alex G. Espinosa",
        "profile_header_role": "Ki?n trc su gi?i php AI c?p cao | K? su môi tru?ng | ¿Qué?n lý d? n",
        "app_tratamiento_title": "H? th?ng x? lý nu?c",
        "app_tratamiento_detail": "?ng d?ng X? lý nu?c qu?n lý cc chu k? l?c và làm s?ch nâng cao. Cung c?p d? li?u th?i gian th?c v? d? c?ng c?a nu?c, m?c pH và hi?u qu? lo?i b? ch?t gây ô nhi?m, cho php b?o trì d? don cc h? th?ng RO công nghi?p.",
        "app_redes_title": "Thi?t k? m?ng lu?i th?y l?c",
        "app_redes_detail": "?ng d?ng Thi?t k? M?ng lu?i Th?y l?c c?a chng tôi cho php mô ph?ng d?ng l?c h?c ch?t l?ng ph?c t?p trong môi tru?ng dân cu và thuong m?i. S? d?ng cc thu?t ton chu?n ISO d? t?i uu ha kch thu?c du?ng ?ng và phân ph?i p su?t, gi?m lãng phv?t li?u và d?m b?o tuân th? UPC/CPC.",
        "app_heaters_title": "My nu?c nng không bình ch?a",
        "app_heaters_detail": "?ng d?ng này t?i uu ha vi?c l?p d?t và hi?u su?t c?a cc h? th?ng làm nng nu?c không bình ch?a. Tnh ton nhu c?u luu lu?ng d?nh và yêu c?u p su?t khd? d?m b?o cung c?p nu?c nng không b? gin do?n, bao g?m m?t mô-dun ch?n don d? kh?c ph?c s? c?.",
        "legal_title": "Khung php lý & B?o m?t m?ng",
        "sec1_title": "K? thu?t Môi tru?ng & B?n v?ng",
        "sec1_legal_p1": "T?t c? n?i dung trên n?n t?ng này, bao g?m nhung không gi?i h?n ? video công ty, hình ?nh 3D du?c t?o, mã ngu?n và c?u trc co s? d? li?u ORION Price Book v6.0 PRO, du?c b?o v? nghiêm ng?t b?i lu?t s? h?u trtu? và b?n quy?n c?a Hoa K? và Bang California.",
        "sec1_legal_li1": "Morales Plumbing gi? quy?n d?c quy?n d?i v?i thuong hi?u, phuong php k? thu?t, co s? khch hàng và danh m?c d?ch v? k? thu?t c?a mình.",
        "sec1_legal_li2": "NeKon AI aGent Consulting gi? quy?n d?ng tc gi? và cc quy?n d?i v?i h? t?ng AI ('Joe AI'), mô hình m?ng th?n kinh, h? th?ng ch?n don th? gic my tnh và công ngh? t? d?ng ha h? th?ng ORION co b?n.",
        "sec1_legal_p2": "Nghiêm c?m sao chp, copy, cào, phân ph?i ho?c s? d?ng thuong m?i tri php b?t k? tài li?u da phuong ti?n nào du?c luu tr? trong h? sinh thi k? thu?t s? này.",
        "sec2_legal_title": "2. B?o m?t m?ng và ¿Quéy?n riêng tu d? li?u",
        "sec2_legal_p1": "Ð?m b?o an toàn cho khch hàng doanh nghi?p (B2B) và dân cu (B2C) c?a chng tôi là uu tiên hàng d?u. T?t c? cc h? th?ng c?a chng tôi ho?t d?ng theo cc giao th?c b?o m?t c?p công nghi?p nghiêm ng?t:",
        "sec2_legal_li1": "Pht hi?n nhi?t và h?ng ngo?i: Vi?c thu th?p d? li?u c?u trc thông qua camera nhi?t d? phân gi?i cao và c?m bi?n chnh xc ch? du?c th?c hi?n cho m?c dch ch?n don v?t lý không xâm l?n.",
        "sec2_legal_li2": "H?p d?ng thông minh và thanh ton: T?t c? ha don và h?p d?ng du?c t?o d?u du?c b?o v? b?ng mã ha d?u cu?i (E2EE).",
        "sec2_legal_li3": "Tuong tc v?i Joe AI: Cc truy v?n g?i cho Joe du?c phân tch ?n danh d? c?i thi?n công c? d? don, d?ng th?i tôn tr?ng quy?n riêng tu c?a ngu?i dùng.",
        "sec3_legal_title": "3. Ph?m vi tham chi?u (SLA)",
        "sec3_legal_p1": "Vi?c cung c?p d?ch v? v?t lý và th?c hi?n k? thu?t ch?u s? qu?n lý c?a Khung chi?n lu?c ORION và B?ng gi. B?ng cch tuong tc v?i n?n t?ng:",
        "sec3_legal_li1": "Khch hàng ch?p nh?n cc c?p d? và di?u kho?n d?ch v? T?t/T?t hon/T?t nh?t phù h?p v?i cc tiêu chu?n c?a Thành ph? San Jose.",
        "sec3_legal_li2": "B?o hành lao d?ng và linh ki?n tuân th? nghiêm ng?t Gi?y php CSLB Class C-36 và cc quy chu?n UPC/CPC.",
        "sec3_legal_li3": "Ði?u ki?n ch?n don k? thu?t s?: Cc bo co do AI t?o ra ch? là bo co so b?. C?n cs? xc nh?n t?i ch? c?a k? thu?t viên ctrình d? d? c?p php cu?i cùng.",
        "contact_loc": "V? tr",
        "contact_email": "Email",
        "contact_phone": "Ði?n tho?i",
        "sec1_desc": "Chng tôi vu?t ra ngoài h? th?ng ?ng nu?c truy?n th?ng b?ng cch tch h?p cc nguyên t?c k? thu?t môi tru?ng vào t?ng thi?t k? th?y l?c. Chng tôi uu tiên hi?u qu? s? d?ng nu?c, x? lý an toàn cc v?t li?u nguy h?i (CSLB C-36 Compliance) và cc h? th?ng không tc d?ng sinh thi trên toàn Bay Area.",
        "sec2_title": "Tch h?p AI & Th? gic My tnh",
        "sec2_desc": "H? th?ng ORION s? d?ng m?ng no-ron d?c quy?n d? pht hi?n rò r? không xâm l?n và ch?n don h?ng ngo?i. Th? gic my tnh cho php chng tôi l?p b?n d? co s? h? t?ng v?i d? chnh xc milimet, t?i uu ha chi phvà ti?n d? th?c hi?n.",
        "sec3_title": "¿Quéy trình Chi?n lu?c (ORION Framework)",
