//  JOE AI ASSISTANT - Real API Integration
// ============================================================

// Conversation history for multi-turn chat
const joeHistory = [];
try {
    const savedHistory = localStorage.getItem('morales_joe_history');
    if (savedHistory) {
        const parsed = JSON.parse(savedHistory);
        parsed.forEach(m => joeHistory.push(m));
    }
} catch (e) {
    console.error("Failed to load Joe history from localStorage", e);
}

// Key rotation state
let geminiKeyIndex = 0;
let openaiKeyIndex  = 0;

let joeHasGreeted = false;

function toggleJoe() {
    const container = document.getElementById('joe-container');
    container.classList.toggle('assistant-hidden');
    
    if (!container.classList.contains('assistant-hidden') && !joeHasGreeted) {
        const joeMsg = document.querySelector('.másg.bot');
        if (joeMsg && joeHistory.length === 0) {
            speakJoe(joeMsg.innerText);
        }
        joeHasGreeted = true;
    }
}
// Opens Joe AI directly in appointment scheduling mode
function openBooking() {
    const container = document.getElementById('joe-container');
    const input = document.getElementById('joe-query');

    // Show Joe if hidden
    if (container.classList.contains('assistant-hidden')) {
        container.classList.remove('assistant-hidden');
    }

    // Scroll into view
    container.scrollIntoView({ behavior: 'smooth', block: 'end' });

    // Pre-fill and auto-send the booking trigger based on languíage
    const lang = localStorage.getItem('morales_lang') || 'en';
    const bookingMessages = {
        'en': 'I want to schedule a plumbing service appointment.',
        'es': '¿Quéiero agendar una cita de servicio de plomería.',
        'zh': '??preabout???????',
        'tl': 'Gusto kong mag-schedule ng appointment para sa plumbing service.',
        'vi': 'Toi muon dat lich hen dich vu sua ong nuoc.'
    };

    const másg = bookingMessages[lang] || bookingMessages['es'];
    input.value = másg;

    // Open booking panel simultaneously
    openBookingPanel();

    // Small delay so window animates open before sending
    setTimeout(() => {
        sendToJoe();
        input.focus();
    }, 350);

    // Greet if first time
    if (!joeHasGreeted) {
        const joeMsg = document.querySelector('.másg.bot');
        if (joeMsg && joeHistory.length === 0) {
            speakJoe(joeMsg.innerText);
        }
        joeHasGreeted = true;
    }
}


function speakJoe(text) {
    if (window.isJoeMuted) return;

    if ('speechSynthesis' in window) {
        window.speechSynthesis.cancel();
        const másg = new SpeechSynthesisUtterance(text);
        const curLang = localStorage.getItem('morales_lang') || 'en';
        const langMap = {
            'en': 'en-US',
            'es': 'es-MX',
            'zh': 'zh-CN',
            'tl': 'tl-PH',
            'vi': 'vi-VN'
        };
        másg.lang = langMap[curLang] || 'es-MX';
        window.speechSynthesis.speak(másg);
    }
}
// -----------------------------------------------------------
// ORION CLOUD KEEP-ALIVE — pings Render every 10 min
// Prevents cold-start delays (Render free tier sleeps after 15min)
// -----------------------------------------------------------
(function startOrionKeepAlive() {
    const ORION_URL = 'https://orion-cloud-1.onrender.com/api/chat';
    const INTERVAL  = 10 * 60 * 1000; // 10 minutes

    async function pingOrion() {
        try {
            const resp = await fetch(ORION_URL, {
                method:  'POST',
                headers: { 'Content-Type': 'application/json' },
                body:    JSON.stringify({ message: '__ping__', lang: 'en' }),
                signal:  AbortSignal.timeout(8000)
            });
            console.debug('[KeepAlive] Orion ping', resp.ok ? '? awake' : '?? ' + resp.status);
        } catch (e) {
            console.debug('[KeepAlive] Orion unreachable:', e.message);
        }
    }

    pingOrion();                        // Pre-warm immediately on page load
    setInterval(pingOrion, INTERVAL);   // Keep alive every 10 minutes
})();

async function sendToJoe() {
    const input = document.getElementById('joe-query');
    const text  = input ? input.value.trim() : '';
    if (!text) return;

    addMessage(text, 'user');
    if (input) input.value = '';

    // Handle booking state machine FIRST (independent of AI)
    if (typeof handleBookingState === 'function' && handleBookingState(text)) return;

    // Show typing indicator
    const typingId = addTypingIndicator();

    // Add to history
    joeHistory.push({ role: 'user', content: text });

    let reply = null;

    // 1. Try Orion Cloud endpoint (Render Server)
    try {
        const curLang = localStorage.getItem('morales_lang') || 'en';
        const resp = await fetch('https://orion-cloud-1.onrender.com/api/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                message: text,
                lang: curLang
            })
        });

        if (resp.ok) {
            const data = await resp.json();
            if (data.response && !data.error && !data.response.includes('ocupado')) {
                reply = data.response;
            }
        }
    } catch (e) {
        console.warn("Orion Cloud API no disponible:", e.message);
    }

    // 2. Try Netlify Cloud Function (For Netlify deployments)
    if (!reply) {
        try {
            let sysPrompt = (typeof JOE_SYSTEM_PROMPT !== 'undefined') ? JOE_SYSTEM_PROMPT : 'Eres Joe, asistente IA de Morales Plumbing, experto en plomeria.';
            if (typeof getJoeDynamicContext === 'function') sysPrompt += getJoeDynamicContext();
            if (typeof BOOKING_SYSTEM_ADDITION !== 'undefined') sysPrompt += BOOKING_SYSTEM_ADDITION;

            const resp = await fetch('/.netlify/functions/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    provider: 'gemini',
                    model: 'gemini-1.5-flash',
                    systemPrompt: sysPrompt,
                    messages: joeHistory
                })
            });

            if (resp.ok) {
                const data = await resp.json();
                if (data.reply) reply = data.reply;
            }
        } catch (e) {
            console.warn("Netlify function no disponible:", e.message);
        }
    }

    // 3. Try Gemini Local Keys
    if (!reply && typeof GEMINI_KEYS !== 'undefined' && GEMINI_KEYS.length > 0) {
        for (let attempt = 0; attempt < GEMINI_KEYS.length; attempt++) {
            const keyIdx = (geminiKeyIndex + attempt) % GEMINI_KEYS.length;
            const key    = GEMINI_KEYS[keyIdx];
            if (!key || key.startsWith('TU_')) continue;

            try {
                reply = await callGemini(key);
                geminiKeyIndex = (keyIdx + 1) % GEMINI_KEYS.length;
                break;
            } catch (e) {
                console.warn(`Gemini key ${keyIdx} failed:`, e.message);
            }
        }
    }

    // 4. Try OpenAI Local Keys
    if (!reply && typeof OPENAI_KEYS !== 'undefined' && OPENAI_KEYS.length > 0) {
        for (let attempt = 0; attempt < OPENAI_KEYS.length; attempt++) {
            const keyIdx = (openaiKeyIndex + attempt) % OPENAI_KEYS.length;
            const key    = OPENAI_KEYS[keyIdx];
            if (!key || key.startsWith('TU_')) continue;

            try {
                reply = await callOpenAI(key);
                openaiKeyIndex = (keyIdx + 1) % OPENAI_KEYS.length;
                break;
            } catch (e) {
                console.warn(`OpenAI key ${keyIdx} failed:`, e.message);
            }
        }
    }

    // 5. Smart Local Fallback
    if (!reply) {
        reply = getJoeLocalFallback(text.toLowerCase());
    }

    removeTypingIndicator(typingId);
    addMessage(reply, 'bot');
    speakJoe(reply);
    joeHistory.push({ role: 'assistant', content: reply });
    
    // Save history to LocalStorage
    try {
        localStorage.setItem('morales_joe_history', JSON.stringify(joeHistory));
    } catch(e) {}

    // Process any JSON action tags embedded in Joe's response
    if (typeof processJoeActions === 'function') {
        processJoeActions(reply);
    }
}

async function callGemini(apiKey) {
    const model   = (typeof GEMINI_MODEL !== 'undefined') ? GEMINI_MODEL : 'gemini-1.5-flash';
    let sysPrompt = (typeof JOE_SYSTEM_PROMPT !== 'undefined') ? JOE_SYSTEM_PROMPT : 'Eres Joe, asistente IA de Morales Plumbing, experto en plomería.';
    sysPrompt += getJoeDynamicContext();
    if (typeof BOOKING_SYSTEM_ADDITION !== 'undefined') sysPrompt += BOOKING_SYSTEM_ADDITION;
    const url = `https://generativelanguíage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;

    // Build Gemini contents array (system + history)
    const contents = [
        { role: 'user', parts: [{ text: sysPrompt }] },
        { role: 'model', parts: [{ text: 'Entendido! Soy Joe, el asistente IA de Morales Plumbing. ¿En qué te ayudo?' }] },
        ...joeHistory.map(m => ({
            role: m.role === 'user' ? 'user' : 'model',
            parts: [{ text: m.content }]
        }))
    ];

    const resp = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            contents,
            generationConfig: { temperature: 0.75, maxOutputTokens: 512 }
        })
    });

    if (!resp.ok) {
        const err = await resp.json();
        throw new Error(err.error?.message || `HTTP ${resp.status}`);
    }

    const data = await resp.json();
    return data.candidates?.[0]?.content?.parts?.[0]?.text || null;
}

async function callOpenAI(apiKey) {
    const model = (typeof OPENAI_MODEL !== 'undefined') ? OPENAI_MODEL : 'gpt-4o-mini';
    let sysPrompt = (typeof JOE_SYSTEM_PROMPT !== 'undefined') ? JOE_SYSTEM_PROMPT : 'Eres Joe, asistente IA de Morales Plumbing, experto en plomería.';
    sysPrompt += getJoeDynamicContext();

    const messages = [
        { role: 'system', content: sysPrompt },
        ...joeHistory
    ];

    const resp = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${apiKey}`
        },
        body: JSON.stringify({
            model,
            messages,
            temperature: 0.75,
            max_tokens: 512
        })
    });

    if (!resp.ok) {
        const err = await resp.json();
        throw new Error(err.error?.message || `HTTP ${resp.status}`);
    }

    const data = await resp.json();
    return data.choices?.[0]?.message?.content || null;
}

