// ============================================================
//  WATER RIPPLE CANVAS EFFECT
// ============================================================
function initWarpCanvas() {
    const canvas = document.getElementById('warp-canvas');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');

    let W, H, cx, cy;
    const STAR_COUNT = 400;
    const MAX_R = 1.5;
    const SPEED = 0.6; // slow, circular expansion like water

    // ? CRITICAL: call resize() BEFORE creating any ripples
    function resize() {
        W = canvas.width  = window.innerWidth;
        H = canvas.height = window.innerHeight;
        cx = W / 2;
        cy = H / 2;
    }
    resize(); // <-- must be FIRST

    function createStar(spread) {
        const angle = Math.random() * Math.PI * 2;
        const dist  = Math.random() * 3 + 0.5;
        const vx = Math.cos(angle);
        const vy = Math.sin(angle);
        const f  = spread !== undefined ? spread : 0;
        return {
            x:  cx + vx * (Math.hypot(W, H) * 0.5 * f + dist),
            y:  cy + vy * (Math.hypot(W, H) * 0.5 * f + dist),
            px: cx + vx * (Math.hypot(W, H) * 0.5 * f),
            py: cy + vy * (Math.hypot(W, H) * 0.5 * f),
            vx, vy,
            speed: Math.random() * SPEED * 0.7 + SPEED * 0.3,
            size:  Math.random() * MAX_R * 0.5 + 0.3,
            color: Math.random() < 0.12
                ? 'rgba(0,229,255,'
                : Math.random() < 0.08
                    ? 'rgba(245,166,35,'
                    : 'rgba(220,235,255,'
        };
    }

    function resetStar(s) {
        const ns = createStar(0);
        Object.assign(s, ns);
    }

    const stars = [];
    // Pre-spread stars across the field so canvas is lively immediately
    for (let i = 0; i < STAR_COUNT; i++) {
        stars.push(createStar(Math.random()));
    }

    function draw() {
        // Semi-transparent black overlay creates the streak/trail effect
        ctx.fillStyle = 'rgba(0,0,0,0.15)';
        ctx.fillRect(0, 0, W, H);

        for (let i = 0; i < stars.length; i++) {
            const s = stars[i];

            // Accelerate as star gets further from center
            const distFromCenter = Math.hypot(s.x - cx, s.y - cy);
            const speedMult = 1 + (distFromCenter / Math.min(W, H)) * 5;

            s.px = s.x;
            s.py = s.y;
            s.x += s.vx * s.speed * speedMult * 0.55;
            s.y += s.vy * s.speed * speedMult * 0.55;

            if (s.x < -10 || s.x > W + 10 || s.y < -10 || s.y > H + 10) {
                resetStar(s);
                continue;
            }

            const sizeFactor = Math.min(1, distFromCenter / (Math.hypot(W, H) * 0.45));
            const curSize    = s.size + sizeFactor * MAX_R * 2;
            const alpha      = Math.min(0.95, 0.25 + sizeFactor * 0.75);

            // Streak line
            ctx.beginPath();
            ctx.strokeStyle = s.color + alpha + ')';
            ctx.lineWidth   = curSize;
            ctx.lineCap     = 'round';
            ctx.moveTo(s.px, s.py);
            ctx.lineTo(s.x,  s.y);
            ctx.stroke();

            // Bright tip dot
            ctx.beginPath();
            ctx.fillStyle = s.color + Math.min(1, alpha + 0.25) + ')';
            ctx.arc(s.x, s.y, curSize * 0.7, 0, Math.PI * 2);
            ctx.fill();
        }

        requestáAnimationFrame(draw);
    }

    window.addEventListener('resize', () => {
        resize();
        // Re-spread stars on resize so they fill the new dimensions
        for (let i = 0; i < stars.length; i++) {
            const ns = createStar(Math.random() * 0.8);
            Object.assign(stars[i], ns);
        }
    });

    draw();
}

// Initialization
document.addEventListener('DOMContentLoaded', () => {
    // Render persisted chat history if any
    try {
        const container = document.getElementById('joe-messages');
        if (container && joeHistory.length > 0) {
            container.innerHTML = ''; // clear default greeting
            joeHistory.forEach(m => {
                addMessage(m.content, m.role === 'user' ? 'user' : 'bot');
            });
        }
    } catch(e) {
        console.error(e);
    }
    
    // Auto-trigger translation for all pages
    if (typeof setLanguage === 'function') {
        const currentLang = localStorage.getItem('morales_lang') || 'en';
        setLanguage(currentLang);
    }
    
    // Initialize Portal UI
    try {
        populateServiceDropdown();
        // Load profile inputs
        const profile = loadClientProfile();
        const nameInput = document.getElementById('profile-name-input');
        const phoneInput = document.getElementById('profile-phone-input');
        const emailInput = document.getElementById('profile-email-input');
        if (nameInput) nameInput.value = profile.name || "";
        if (phoneInput) phoneInput.value = profile.phone || "";
        if (emailInput) emailInput.value = profile.email || "";
        
        updateMembershipCardsUI();
        updatePortalUI();
    } catch(e) {
        console.error("Portal initialization failed:", e);
    }

    // Warp speed canvas
    initWarpCanvas();

    // Parallax star layers on mouse move
    const layers = document.querySelectorAll('.layer');
    window.addEventListener('mousemove', (e) => {
        const x = (e.clientX / window.innerWidth) - 0.5;
        const y = (e.clientY / window.innerHeight) - 0.5;
        layers.forEach((layer, i) => {
            const depth = (i + 1) * 15;
            layer.style.transform = `translate(${x * depth}px, ${y * depth}px)`;
        });
    });

    // -- PUBLIC CONTACT FORM SUBMISSION --
    window.submitPublicContact = async function(e) {
        e.preventDefault();
        const btn = document.getElementById('pc-btn');
        let oldText = 'Send Message';
        if (btn) {
            btn.disabled = true;
            oldText = btn.innerText;
            btn.innerText = 'Enviando...';
        }

        const form = document.getElementById('public-contact-form');
        
        const data = {
            name: document.getElementById('pc-name').value,
            phone: document.getElementById('pc-phone').value,
            email: document.getElementById('pc-email').value,
            notes: document.getElementById('pc-message').value,
            service: 'Contact Form',
            date: new Date().toLocaleDateString(),
            time: new Date().toLocaleTimeString(),
            id: Date.now().toString()
        };

        try {
            if (window.MoralesFirebase && window.MoralesFirebase.saveContactMessage) {
                await window.MoralesFirebase.saveContactMessage(data);
            } else {
                console.warn('Firebase not ready, could not save message.');
            }

            if (btn) btn.innerText = '? Mensaje Enviado';
            if (form) form.reset();
            
            const waMessage = `Hola Morales Plumbing!%0ANueva solicitud de contacto:%0A*Nombre:* ${data.name}%0A*Tel:* ${data.phone}%0A*Email:* ${data.email}%0A*Mensaje:* ${data.notes}`;
            window.open('https://wa.me/16692134422?text=' + waMessage, '_blank');
            
            setTimeout(() => {
                if (btn) {
                    btn.disabled = false;
                    btn.innerText = oldText;
                }
            }, 4000);
        } catch (err) {
            console.warn('Error sending contact form:', err);
            if (btn) btn.innerText = '? Mensaje Enviado'; // Fake success to not break UX
            if (form) form.reset();
            setTimeout(() => {
                if (btn) {
                    btn.disabled = false;
                    btn.innerText = oldText;
                }
            }, 4000);
        }
    }

    // Default Languíage
    const savedLang = localStorage.getItem('morales_lang') || 'en';
    setLanguage(savedLang);

    // Link Nav - Fix: only prevent default for internal hash links
    document.querySelectorAll('.nav-links a').forEach(link => {
        link.addEventListener('click', (e) => {
            const href = link.getAttribute('href');
            if (href.startsWith('#')) {
                e.preventDefault();
                navigate(href.substring(1));
            }
            // External/Subfolder links (like docs/pricebook.html) will work normally
        });
    });

    // Joe Input
    const joeQuery = document.getElementById('joe-query');
    if (joeQuery) {
        joeQuery.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') sendToJoe();
        });
    }

    // Global Languíage Button Binding
    document.addEventListener('click', (e) => {
        const btn = e.target.closestá('.lang-btn');
        if (btn && btn.hasAttribute('data-lang')) {
            setLanguage(btn.getAttribute('data-lang'));
        }
    });

    // Initial Navigation based on hash
    const initialSection = window.location.hash.substring(1) || 'home';
    navigate(initialSection, false);

    // CCPA Banner Check
    if (!localStorage.getItem('ccpa_accepted')) {
        const banner = document.getElementById('ccpa-cookie-banner');
        if (banner) {
            banner.style.display = 'flex';
        }
    }
});


