    "ai_intro_2": "T?i Morales Plumbing, chúng tôi dã b? l?i phía sau k? nguyên d? doán th? công d? bu?c vào k? nguyên c?a 'd? chính xác ph?u thu?t'. B?n không ch? là nh?ng ngu?i h?c vi?c; b?n là nh?ng chuyên gia k? thu?t m?i c?a Thung lung Silicon, m?t l?c lu?ng ho?t d?ng k?t h?p m? hôi c?a ngh? v?i b? não c?a trí tu? nhân t?o c?p d? quân s?.",
    "ai_intro_3": "Hãy nhìn vào chi?c khiên c?a chúng tôi: gi?t nu?c trong m? b?o v? m?t vi m?ch bên trong không ch? là m?t thi?t k?. Nó tu?ng trung cho tri?t lý 'Tech-Service' c?a chúng tôi: kh? nang ki?m soát dòng ch?y tuy?t d?i thông qua d?i m?i k? thu?t s?.",
    "ai_quote": "\"S? m?nh c?a chúng tôi là cung c?p các gi?i pháp ch?t lu?ng cao nh?t, k?t h?p kinh nghi?m k? thu?t th? công v?i công ngh? AI tiên ti?n d? b?o v? s?c kh?e c?ng d?ng và s? toàn v?n c?a ngôi nhà m?t cách nhanh chóng và d?t khoát.\" — Tri?t lý Morales Plumbing",
    "ai_intro_4": "Tâm lý tiên phong này là di?u ngan cách m?t th? s?a ?ng nu?c thông thu?ng v?i m?t c? v?n công ngh? c?a H?c vi?n Morales. Ð? làm ch? môi tru?ng này, công c? d?u tiên c?a b?n s? không ph?i là dèn xì, mà là phi công ph? k? thu?t s? c?a b?n.",
    "ai_s1_title": "1. Phi công ph? k? thu?t s? c?a b?n: Joe AI là ai?",
    "ai_s1_p1": "Trên chi?n tru?ng co s? h? t?ng nu?c, ki?n th?c là s?c m?nh. Joe AI là tr? lý ?o da phuong th?c c?a chúng tôi, m?t Mô hình ngôn ng? l?n (LLM) dã du?c tinh ch?nh riêng v?i Quy d?nh H? th?ng ?ng nu?c California (CPC) và so d? k? thu?t c?a các nhà s?n xu?t hàng d?u. Joe không 'doán'; Joe x? lý d? li?u véc to trong th?i gian th?c.",
    "ai_s1_p2": "Thông qua Nh?n d?ng Ký t? Quang h?c (OCR), b?n có th? quét bi?n d? li?u c?a b?t k? thi?t b? nào và Joe AI s? cung c?p, trong vòng chua d?y 3 giây, hu?ng d?n s? d?ng chính xác và so d? ch?n doán t?ng bu?c. Công c? này là lý do t?i sao chúng tôi gi?m 40% th?i gian ch?n doán.",
    "ai_t_h1": "Ð?c tính",
