    "ai_t_r4_2": "Ch?m, d? ph?i d?n l?n th? hai.",
    "ai_t_r4_3": "Nhanh hon 40%; gi?i quy?t ngay trong cu?c h?n d?u tiên.",
    "ai_s1_p3": "Hi?u qu? này cho phép chúng tôi không th? sai l?m không ch? v? m?t k? thu?t, mà còn trong vi?c b?o v? quy d?nh c?a t?ng can thi?p.",
    "ai_s2_title": "2. PlumbAssist AI: Ð?m b?o Tuân th? K? thu?t c?a b?n",
    "ai_s2_p1": "Là nh?ng ngu?i uu tú c?a California, chúng tôi ho?t d?ng du?i kính hi?n vi pháp lý. PlumbAssist AI là ngu?i b?o v? tuân th? c?a b?n. Khi b?n làm vi?c, h? th?ng này tham chi?u chéo m?i quy?t d?nh v?i Quy d?nh H? th?ng ?ng nu?c California (CPC) theo th?i gian th?c. Nhung ch?c nang c?a nó vu?t ra ngoài các quy d?nh k? thu?t; nó du?c tích h?p v?i Trình t?o pháp lý Morales. H? th?ng này t? d?ng t?o ra các tài li?u quan tr?ng d? b?o v? trách nhi?m c?a chúng tôi và quy?n l?i c?a khách hàng, d?m b?o m?i h?p d?ng d?u không th? xuyên th?ng.",
    "ai_s2_li1": "<strong>An ninh quy d?nh:</strong> Tra c?u CPC ngay l?p t?c, lo?i b? l?i do ghi nh? kém.",
    "ai_s2_li2": "<strong>Qu?n lý tài li?u t? d?ng:</strong> T?o ngay thông báo 'Quy?n h?y b?' và tài li?u 'Thông báo cho Ch? s? h?u' (NTO) d? b?o v? quy?n c?m c? máy móc c?a chúng tôi.",
    "ai_s2_li3": "<strong>Lá ch?n trách nhi?m:</strong> T?o các t? b? tùy ch?nh tru?c khi b?t d?u b?t k? công vi?c phá h?y nào.",
    "ai_s2_p2": "D? li?u và lu?t pháp b?o v? trách nhi?m c?a chúng tôi, nhung các c?m bi?n cho phép chúng tôi nhìn xuyên qua bê tông r?n.",
    "ai_s3_title": "3. Nhìn th?y Ði?u vô hình: Ch?p ?nh nhi?t FLIR v?i Trí tu? nhân t?o",
    "ai_s3_p1": "Ð? d?t du?c d? chính xác c?p d? quân s? th?c s?, chúng tôi s? d?ng camera ?nh nhi?t có d? phân gi?i cao (ki?u máy FLIR E8-XT ho?c C5). B?ng cách tích h?p các camera này v?i các thu?t toán AI, chúng tôi th?c hi?n 'B?n d? nhi?t' d? xác d?nh d? d?c nhi?t d? mà m?t ngu?i không nhìn th?y du?c.",
    "ai_s3_p2": "Ði?u này cho phép chúng tôi phát hi?n 's? b?t thu?ng c?a hoa' —hi?u ?ng kh?i nhi?t ho?c 't?o lông' do nu?c nóng thoát ra du?i l?p bê tông t?o ra— d?nh v? các rò r? t?m (slab leaks) mà không c?n phá d? không c?n thi?t. Công ngh? MSX (Multi-Spectral Dynamic Imaging) cao c?p trích xu?t chi ti?t c?u trúc t? camera hình ?nh và d?p n?i chúng trên ?nh nhi?t.",
    "ai_s3_p3": "Nh? MSX và x? lý AI, biên d? sai s? khi d?nh v? v? trí v? du?i l?p bê tông du?c gi?m xu?ng du?i 3 inch vuông. Khi chúng tôi dã 'nhìn th?y' cái vô hình, bu?c ti?p theo là dua ra gi?i pháp v?i m?c d? tinh vi công ngh? tuong t?.",
    "ai_s4_title": "4. Máy tính b?ng là Công c? Ðóng c?a: S? giá Orion",
    "ai_s4_p1": "S? chuyên nghi?p c?c d? du?c c?ng c? vào th?i di?m báo giá. H? th?ng POS Orion Price Book s? d?ng tâm lý bán hàng d? lo?i b? xích mích v? giá c?. Chúng tôi luôn dua ra ba l?a ch?n: 'T?t, T?t hon, T?t nh?t'.",
    "ai_s4_p2": "Là ngu?i hu?ng d?n, chúng tôi d?y b?n bí m?t: l?a ch?n 'T?t nh?t' (Cao c?p) ho?t d?ng nhu m?t di?m neo giá, khi?n l?a ch?n 'T?t hon' (Khuy?n ngh?) du?c coi là giá tr? h?p lý cao nh?t. Ðây là noi chúng tôi bi?n m?t s?a ch?a thành m?t nâng c?p tài s?n. Ð? ch?t don hàng thành công, hãy làm theo quy trình này trên máy tính b?ng c?a b?n:",
    "ai_s4_li1": "<strong>B?ng ch?ng tr?c quan:</strong> Cho khách hàng xem hình ?nh t? camera FLIR và báo cáo c?a Joe AI.",
    "ai_s4_li2": "<strong>Ðua ra các tùy ch?n:</strong> Cung c?p các gi?i pháp th?c t?, nhu Navien NPE-240A d? có nu?c nóng vô t?n ho?c h? th?ng làm l?i du?ng ?ng toàn di?n v?i Uponor PEX-A.",
    "ai_s4_li3": "<strong>Minh b?ch v? Giá c? d?nh:</strong> S? d?ng giá c? rõ ràng. Khách hàng tr? ti?n cho gi?i pháp, không ph?i cho s? gi? b?n dành t?i ch?.",
    "ai_s4_li4": "<strong>Ðóng và Ch? ký h?p pháp:</strong> Khách hàng ký h?p d?ng do Trình t?o pháp lý Morales t?o, nh?n b?n sao k? thu?t s? c?a h? ngay l?p t?c.",
    "ai_s4_p3": "Quy trình này t?o ra 's? chuyên nghi?p siêu vi?t' gi?i thích cho m?c giá cao c?p c?a chúng tôi và c?ng c? th?m quy?n c?a b?n v?i khách hàng.",
    "ai_s5_title": "5. K?t lu?n: K? thu?t viên c?a Ngày mai",
    "ai_s5_p1": "T?i H?c vi?n Morales, chúng tôi không dào t?o b?n thành th? s?a ?ng nu?c; chúng tôi dang dào t?o b?n qu?n lý m?t h? sinh thái công ngh? cao. B?ng cách làm ch? Joe AI, phép do nhi?t d? c?p d? quân s? và h? th?ng Orion, chúng tôi d?m b?o t? l? gi?i quy?t l?n d?u trên 95%.",
    "ai_s5_p2": "B?n là tuong lai c?a m?t ngành ngh? du?c khoa h?c vinh danh. B?n không ch? s?a ch?a du?ng ?ng; b?n b?o v? co s? h? t?ng c?a Thung lung Silicon v?i d? chính xác c?a m?t bác si ph?u thu?t và trí thông minh c?a m?t k? su d? li?u. Hãy nh?: s? d?i m?i và ph?m giá k? thu?t là bi?u ng? c?a chúng tôi. Chào m?ng d?n v?i nh?ng ngu?i uu tú.",
